$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($q='')=>CompanyRequestScope::adminUrl($this,'company_expenses'.$q);
$hidden=function(string $action)use($esc,$company_expenses_csrf){echo '<input type="hidden" name="action" value="'.$esc($action).'"><input type="hidden" name="company_expenses_csrf" value="'.$esc($company_expenses_csrf).'"><input type="hidden" name="request_key" value="'.bin2hex(random_bytes(32)).'">';};
?>
<section class="company-settings-card"><h1>Despesas da empresa</h1><p>Registros privados da empresa ativa. Registrar uma despesa não executa pagamento, boleto ou transferência.</p>
<?php if($error){?><p role="alert" class="alert alert-danger"><?= $esc($error); ?></p><p><a href="<?= $esc($url()); ?>">Reabrir a lista</a></p><?php } ?>
<?php if($detail){?><h2>DES-<?= str_pad((string)$detail['number'],6,'0',STR_PAD_LEFT); ?> — <?= $detail['state']==='recorded'?'Registrada':'Cancelada'; ?></h2>
<p><?= $esc($detail['description']); ?> · <?= $esc($detail['expense_date']); ?> · <?= $esc($detail['category_name']); ?></p><p><?= $esc($detail['currency']); ?> <?= $esc(CompanyExpenses::money((int)$detail['total_cents'])); ?> (base <?= $esc(CompanyExpenses::money((int)$detail['amount_cents'])); ?> + tributo <?= $esc(CompanyExpenses::money((int)$detail['tax_cents'])); ?>)</p>
<?php if($detail['project_name']!==''){?><p>Projeto no registro: <?= $esc($detail['project_name']); ?></p><?php } ?>
<?php if($detail['client_name']!==''){?><p>Cliente no registro: <?= $esc($detail['client_name']); ?></p><?php } ?><p><?= nl2br($esc($detail['note'])); ?></p>
<?php require APPPATH.'views/admin/companies/expense_billing.php'; ?>
<h3>Comprovantes privados</h3><?php if(!$files){?><p>Nenhum comprovante ativo.</p><?php }else{?><ul><?php foreach($files as $file){?><li><a href="<?= $esc($url('?expense='.(int)$detail['id'].'&file='.$file['file_key'])); ?>"><?= $esc($file['filename']); ?></a> · <?= (int)$file['byte_size']; ?> bytes<?php if($capabilities['edit']){?><?= form_open($url());$hidden('file_hide'); ?><input type="hidden" name="expense_id" value="<?= (int)$detail['id']; ?>"><input type="hidden" name="file_key" value="<?= $esc($file['file_key']); ?>"><input type="hidden" name="content_hash" value="<?= $esc($file['content_hash']); ?>"><button type="submit">Ocultar comprovante; preservar histórico</button><?= form_close(); ?><?php } ?></li><?php } ?></ul><?php } ?>
<?php if($detail['state']==='recorded'&&$capabilities['edit']){?><?= form_open_multipart($url());$hidden('file_upload'); ?><input type="hidden" name="expense_id" value="<?= (int)$detail['id']; ?>"><label for="expense-file">Comprovante PDF, PNG ou JPEG</label><input class="form-control" id="expense-file" type="file" name="expense_file" accept=".pdf,.png,.jpg,.jpeg" required><p>PDF até 2 MiB; imagens até 512 KiB e 1600 pixels, regravadas em PNG. Até 20 uploads e 20 MiB no histórico. Downloads são privados e auditados, sem exibição no portal.</p><button type="submit">Adicionar comprovante privado</button><?= form_close(); ?><?php } ?>
<?php if($detail['state']==='recorded'&&$capabilities['edit']&&!in_array($billing['state']??'', ['converting','converted'],true)){?><h3>Editar registro</h3><?= form_open($url());$hidden('update'); ?><input type="hidden" name="expense_id" value="<?= (int)$detail['id']; ?>"><input type="hidden" name="revision" value="<?= $esc($detail['revision_token']); ?>"><?php $values=$detail;$field='edit';require APPPATH.'views/admin/companies/expense_fields.php'; ?><button type="submit">Salvar despesa</button><?= form_close(); ?><?php } ?>
<?php if($detail['state']==='recorded'&&$capabilities['delete']&&!in_array($billing['state']??'', ['converting','converted'],true)){?><?= form_open($url());$hidden('cancel'); ?><input type="hidden" name="expense_id" value="<?= (int)$detail['id']; ?>"><input type="hidden" name="revision" value="<?= $esc($detail['revision_token']); ?>"><p>O cancelamento conserva os valores, o número e o histórico.</p><button type="submit">Cancelar registro da despesa</button><?= form_close(); ?><?php } ?><p><a href="<?= $esc($url()); ?>">Voltar à lista</a></p><?php } ?>
<h2>Lista da empresa</h2><form method="get" action="<?= $esc($url()); ?>"><label for="expense-search">Buscar descrição ou categoria</label><input class="form-control" id="expense-search" name="search" maxlength="191" value="<?= $esc($search); ?>"><button type="submit">Buscar</button></form>
<div class="table-responsive"><table class="table"><thead><tr><th>Número</th><th>Data</th><th>Descrição</th><th>Categoria</th><th>Total</th><th>Estado</th></tr></thead><tbody><?php foreach($directory['items'] as $row){?><tr><td><a href="<?= $esc($url('?expense='.(int)$row['id'])); ?>">DES-<?= str_pad((string)$row['number'],6,'0',STR_PAD_LEFT); ?></a></td><td><?= $esc($row['expense_date']); ?></td><td><?= $esc($row['description']); ?></td><td><?= $esc($row['category_name']); ?></td><td><?= $esc($row['currency'].' '.CompanyExpenses::money((int)$row['total_cents'])); ?></td><td><?= $row['state']==='recorded'?'Registrada':'Cancelada'; ?></td></tr><?php } ?></tbody></table></div>
<?php if($directory['next']!==null){?><a href="<?= $esc($url('?after='.$directory['next'].'&search='.rawurlencode($search))); ?>">Próxima página</a><?php } ?>
<?php if($capabilities['create']){?><h2>Registrar despesa</h2><?php if(!$categories){?><p>Cadastre antes uma categoria da empresa abaixo.</p><?php } ?><?= form_open($url());$hidden('create');$values=[];$field='new';require APPPATH.'views/admin/companies/expense_fields.php'; ?><button type="submit">Registrar despesa da empresa</button><?= form_close(); ?>
<h2>Categorias desta empresa</h2><?= form_open($url());$hidden('category'); ?><label for="category-new">Nova categoria</label><input id="category-new" class="form-control" name="category_name" maxlength="191" required><input type="hidden" name="category_active" value="1"><button type="submit">Adicionar categoria</button><?= form_close(); ?><?php } ?>
<?php if($capabilities['edit']){foreach($categories as $category){?><?= form_open($url());$hidden('category'); ?><input type="hidden" name="category_id" value="<?= (int)$category['id']; ?>"><input type="hidden" name="revision" value="<?= $esc($category['revision_token']); ?>"><label>Nome da categoria<input class="form-control" name="category_name" maxlength="191" value="<?= $esc($category['name']); ?>" required></label><label><input type="checkbox" name="category_active" value="1" <?= (int)$category['active']===1?'checked':''; ?>> Ativa para novos registros</label><button type="submit">Salvar categoria; preservar histórico</button><?= form_close(); ?><?php }} ?>
